const item = $input.first();
const body = item.json.body ?? {};

const reject = (code, reason) => [{
  json: { passed: false, rejectCode: code, rejectReason: reason, body },
}];

if (!body.candidateId) {
  return reject('missing_candidate', 'Missing candidate ID');
}

const transcript = String(body.fullTranscript || '').trim();
if (!transcript) {
  return reject('invalid_transcript', 'Interview transcript is missing');
}

// A one-minute interview cleared this gate and scored 66%: 50 characters and 2
// messages are met by "hello, I'm ready" plus one agent line. What decides whether a
// candidate can be judged is how much THEY said, so measure that instead.
const CAND_RE = /^\s*(candidate|user|المرشح)\s*:\s*/i;
const candidateTurns = transcript
  .split(/\r?\n+/)
  .filter((l) => CAND_RE.test(l))
  .map((l) => l.replace(CAND_RE, '').trim())
  .filter(Boolean);
const wordCount = (t) => t.split(/\s+/).filter(Boolean).length;
const candidateWords = candidateTurns.reduce((n, t) => n + wordCount(t), 0);
const substantiveAnswers = candidateTurns.filter((t) => wordCount(t) >= 4).length;

// Only judge when the transcript is parseable; an unrecognised format falls back to
// the old length check rather than blocking a real interview on a parsing guess.
if (candidateTurns.length > 0) {
  if (candidateWords < 40 || substantiveAnswers < 3) {
    return reject(
      'insufficient_evidence',
      'Candidate said too little to score (' + candidateWords + ' words, ' + substantiveAnswers + ' substantive answers)'
    );
  }
} else if (transcript.length < 50) {
  return reject('invalid_transcript', 'Interview transcript is missing or too short');
}

const messageCount = Number(body.messageCount ?? 0);
if (messageCount < 2) {
  return reject('insufficient_messages', 'Interview must contain at least 2 messages');
}

const evaluation = body.evaluation ?? {};
for (const key of ['communicationSkills', 'englishFluency', 'confidenceLevel']) {
  if (evaluation[key] === undefined || evaluation[key] === null || evaluation[key] === '') {
    return reject('missing_metrics', `Missing evaluation metric: ${key}`);
  }
}

if (body.criteria) {
  try {
    const criteria = typeof body.criteria === 'string' ? JSON.parse(body.criteria) : body.criteria;
    if (!Array.isArray(criteria) || criteria.length === 0) {
      throw new Error('empty criteria');
    }
  } catch {
    return reject('invalid_criteria', 'Criteria must be a valid non-empty JSON array');
  }
}

return [{
  json: { passed: true, rejectCode: '', rejectReason: '', body },
}];

const row = $input.first().json;
const body = $('Webhook').first().json.body || {};

function parseScore(score) {
  if (score == null) return 0;
  const s = String(score);
  const slash = s.match(/(\d+(?:\.\d+)?)\s*\/\s*100/);
  if (slash) return Number(slash[1]);
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

const candidateId = String(row.CandidateID || body.candidateId || '').trim();
if (!candidateId) return [];

const scoreNum = parseScore(row.OverallScore);
const applicantName = String(
  row.ApplicantName || body.full_name || body.fullName || body.candidateName || ''
).trim() || `Candidate ${candidateId.slice(-6)}`;

return [{
  json: {
    ...row,
    CandidateID: candidateId,
    CampaignID: String(row.CampaignID || body.campaignId || body.campaignID || '').trim(),
    ApplicantName: applicantName,
    OverallScoreNumeric: scoreNum,
    OverallScore: String(scoreNum),
  },
}];

const items = $input.all();
return items.map((item) => {
  const body = item.json.body ?? {};
  const callbackUrl = String(body.callbackUrl || '').trim();
  const inboundSecret = String(body.inboundSecret || '').trim();
  const candidateId = String(body.candidateId || '').trim();
  const inputValid = Boolean(callbackUrl && inboundSecret && candidateId);
  return {
    ...item,
    json: {
      ...item.json,
      __evaaloStageSecurity: {
        ...(item.json.__evaaloStageSecurity ?? {}),
        inputValid,
      },
    },
  };
});

const items = $input.all();
return items.map((item) => {
  const body = item.json.body ?? {};
  const callbackUrlRaw = String(body.callbackUrl || '').trim();

  const ALLOWED_ORIGINS = new Set([
    'https://api.evaalo.com',
    'http://100.73.82.78:5000',
    'http://localhost:5000',
    'http://127.0.0.1:5000',
  ]);
  const ALLOWED_PATHS = new Set([
    '/webhook/n8n/stage1',
    '/webhook/n8n/stage2',
    '/webhook/n8n/stage3',
    '/webhook/n8n/video',
  ]);
  const REQUIRED_QUERY_KEYS = ['candidateId', 'mode', 'sessionId', 'campaignId', 'issuedAt', 'expiresAt', 'token'];

  let urlValid = false;
  let urlRejectReason = '';
  if (callbackUrlRaw && !callbackUrlRaw.includes('@')) {
    const m = callbackUrlRaw.match(/^(https?):\/\/([^\/:?#]+)(?::(\d+))?(\/[^?#]*)?(?:\?([^#]*))?/i);
    if (m) {
      const protocol = m[1].toLowerCase();
      const host = m[2];
      const port = m[3] || '';
      const pathname = m[4] || '/';
      const query = m[5] || '';
      const origin = port ? `${protocol}://${host}:${port}` : `${protocol}://${host}`;
      if (!ALLOWED_ORIGINS.has(origin)) {
        urlRejectReason = 'origin';
      } else if (!ALLOWED_PATHS.has(pathname)) {
        urlRejectReason = 'path';
      } else {
        const params = {};
        for (const part of query.split('&')) {
          if (!part) continue;
          const eq = part.indexOf('=');
          const k = eq >= 0 ? decodeURIComponent(part.slice(0, eq)) : decodeURIComponent(part);
          const v = eq >= 0 ? decodeURIComponent(part.slice(eq + 1)) : '';
          params[k] = v;
        }
        const allKeys = REQUIRED_QUERY_KEYS.every((key) => {
          const val = String(params[key] ?? '').trim();
          return val !== '';
        });
        if (!allKeys) {
          urlRejectReason = 'query';
        } else if (params.mode !== 'stage2') {
          urlRejectReason = 'mode';
        } else {
          urlValid = true;
        }
      }
    } else {
      urlRejectReason = 'parse';
    }
  } else {
    urlRejectReason = 'empty';
  }

  return {
    ...item,
    json: {
      ...item.json,
      __evaaloStageSecurity: {
        ...(item.json.__evaaloStageSecurity ?? {}),
        urlValid,
        urlRejectReason,
      },
    },
  };
});

const sec = $json.__evaaloStageSecurity ?? {};
throw new Error(
  `INVALID_STAGE2_CALLBACK: inputValid=${sec.inputValid} urlValid=${sec.urlValid} reason=${sec.urlRejectReason || 'unknown'}`
);

const items = $input.all();
function parseJsonLoose(raw) {
  if (raw == null) return null;
  if (typeof raw === 'object' && !Array.isArray(raw)) return raw;
  if (typeof raw !== 'string') return null;
  let s = raw.trim();
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const m = s.match(/\{[\s\S]*\}/);
  if (m) s = m[0];
  try { return JSON.parse(s); } catch { return null; }
}
function targetLang() {
  const raw = String($('Webhook').first().json.body?.language || 'ar').trim().toLowerCase();
  if (raw === 'en' || raw.startsWith('en-')) return 'en';
  return 'ar';
}
// The callback node sends multipart-form-data, which cannot encode arrays or
// objects. Emit these as JSON strings; the backend parses them back
// (normalizeStringArrayForWebhook for the two lists, buildStage2V2Extras for the
// v2 fields). competencyScores carries the per-competency evidence, which is the
// whole point of the v2 contract - without this line it would arrive as
// "[object Object]" and be dropped.
function coerceArrays(o) {
  if (!o || typeof o !== 'object') return o;
  for (const k of ['Strengths', 'Weaknesses', 'competencyScores', 'not_assessed', 'priors']) {
    if (o[k] && typeof o[k] === 'object') o[k] = JSON.stringify(o[k]);
  }
  return o;
}
return items.map((item) => {
  const original = $('Stage 2 Scoring').first().json.output ?? {};
  if (targetLang() === 'en') {
    return { json: { output: coerceArrays({ ...original }) }, binary: item.binary };
  }
  let o = parseJsonLoose(item.json.output ?? item.json.text ?? item.json);
  if (o && o.output && typeof o.output === 'object') o = o.output;
  const merged = { ...original, ...(o && typeof o === 'object' ? o : {}) };
  return { json: { output: coerceArrays(merged) }, binary: item.binary };
});

